package util;
import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.*;import java.nio.file.*;import javax.imageio.ImageIO;import java.util.*;import model.*;import dao.*;import java.sql.*;import java.time.*;
@WebServlet("/view/management/saveMovie") @MultipartConfig(maxFileSize=5242880,maxRequestSize=6291456)
public class Poster5 extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse res)throws IOException,ServletException{Path saved=null;try{Web5.post(r);Movie5 m=new Movie5();m.setTenPhim(r.getParameter("TenPhim"));m.setTacGia(r.getParameter("TacGia"));m.setTheLoai(r.getParameter("TheLoai"));m.setThoiLuong(Integer.parseInt(r.getParameter("ThoiLuong")));m.setMoTa(r.getParameter("MoTa"));String date=r.getParameter("NgayPhatHanh");m.setNgayPhatHanh(date==null||date.isBlank()?null:LocalDate.parse(date));Part part=r.getPart("poster");m.setApPhich("");if(part!=null&&part.getSize()>0){java.awt.image.BufferedImage im;try(InputStream in=part.getInputStream()){im=ImageIO.read(in);}if(im==null||im.getWidth()>8000||im.getHeight()>8000)throw new IllegalArgumentException("Chỉ nhận ảnh PNG/JPEG tối đa 5 MB, 8000px");Path dir=Paths.get(System.getProperty("catalina.base"),"cinema5-uploads");Files.createDirectories(dir);String name=UUID.randomUUID()+".png";saved=dir.resolve(name);ImageIO.write(im,"png",saved.toFile());m.setApPhich(name);}try(Connection c=DAO5.open()){new MovieDAO5(c).saveMovie(m);}r.getSession().setAttribute("savedMovie",m);res.sendRedirect("GDAddMovieResult5.jsp");}catch(Exception e){if(saved!=null)Files.deleteIfExists(saved);r.getSession().setAttribute("movieError","Không lưu được phim: "+e.getMessage());res.sendRedirect("GDAddMovie5.jsp");}}}
